await spec()
  .post(BASE_URL)
  .withJson({
    query: `mutation { addCategory(name: "Eletrônicos") { id name } }`
  })
  .expectStatus(200)
  .expectJsonLike({
    data: {
      addCategory: {
        id: 1,
        name: 'Eletrônicos'
      }
    }
  })
  .expectJsonSchema({
    type: 'object',
    required: ['data'],
    properties: {
      data: {
        type: 'object',
        required: ['addCategory'],
        properties: {
          addCategory: {
            type: 'object',
            required: ['id', 'name'],
            properties: {
              id: { type: 'number' },
              name: { type: 'string' }
            }
          }
        }
      }
    }
  })

